import { useEffect, useRef } from "react";

export function useTextStrokeObserver() {
  const observerRef = useRef<IntersectionObserver | null>(null);
  const scrollTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const mousePosRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    // Get all text-stroke elements
    const textStrokeElements = document.querySelectorAll('.text-stroke, .text-stroke-accent, .text-stroke-faint');

    if (textStrokeElements.length === 0) return;

    // Create intersection observer
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          const element = entry.target as HTMLElement;

          if (entry.isIntersecting) {
            // When element enters viewport, add filled class
            element.classList.add('text-stroke-filled');
          } else {
            // When element leaves viewport, remove filled class
            element.classList.remove('text-stroke-filled');
          }
        });
      },
      {
        threshold: 0.1, // Trigger when 10% of element is visible
        rootMargin: '0px',
      }
    );

    // Observe all text-stroke elements
    textStrokeElements.forEach((element) => {
      observer.observe(element);
    });

    observerRef.current = observer;

    // Handle scroll to trigger hover when cursor is over text after scroll stops
    const handleScroll = () => {
      // Clear previous timeout
      if (scrollTimeoutRef.current) {
        clearTimeout(scrollTimeoutRef.current);
      }

      // Wait for scroll to stop, then check what's under cursor
      scrollTimeoutRef.current = setTimeout(() => {
        const elementUnderCursor = document.elementFromPoint(mousePosRef.current.x, mousePosRef.current.y);
        if (elementUnderCursor) {
          // Check if the element or its parent is a text-stroke element
          const textStrokeElement = elementUnderCursor.closest('.text-stroke, .text-stroke-accent, .text-stroke-faint') as HTMLElement;

          if (textStrokeElement) {
            // Trigger hover effect
            textStrokeElement.classList.add('text-stroke-filled');
          }
        }
      }, 100); // Wait 100ms after scroll stops
    };

    // Track mouse position
    const handleMouseMove = (e: MouseEvent) => {
      mousePosRef.current = { x: e.clientX, y: e.clientY };
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    window.addEventListener('mousemove', handleMouseMove);

    // Cleanup
    return () => {
      if (observerRef.current) {
        textStrokeElements.forEach((element) => {
          observerRef.current?.unobserve(element);
        });
        observerRef.current.disconnect();
      }
      if (scrollTimeoutRef.current) {
        clearTimeout(scrollTimeoutRef.current);
      }
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);
}

export default useTextStrokeObserver;
